import 'package:flutter/material.dart'; import '../services/discovery_service.dart'; import 'module_detail.dart';
import 'public_profile_screen.dart';
class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen> createState()=>_S();}
class _S extends State<SearchScreen>{final c=TextEditingController();List<Map<String,dynamic>> rows=[];bool loading=false;Future<void>run()async{setState(()=>loading=true);try{rows=await DiscoveryService().search(c.text);}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext x)=>Scaffold(appBar:AppBar(title:TextField(controller:c,autofocus:true,decoration:const InputDecoration(hintText:'Search Africa Link'),onSubmitted:(_)=>run()),actions:[IconButton(onPressed:run,icon:const Icon(Icons.search))]),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:rows.map((r){final type='${r['_type']}';final title='${r['full_name']??r['name']??r['title']??r['username']??'Result'}';return ListTile(leading:Icon(type=='profiles'?Icons.person:Icons.public),title:Text(title),subtitle:Text(type),onTap:()=>Navigator.push(x,MaterialPageRoute(builder:(_)=>type=='profiles'?PublicProfileScreen(profile:r):ModuleDetail(module:type,item:r))));}).toList()));}
